{
  "items": [
    {
      "name": "Finsupp.prod_fintype",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : CommMonoid N] [inst_2 : Fintype α]\n  (f : α →₀ M) (g : α → M → N), (∀ (i : α), g i 0 = 1) → f.prod g = ∏ i, g i (f i)"
    },
    {
      "name": "DFinsupp.prod_eq_prod_fintype",
      "module_name": "Mathlib.Data.DFinsupp.BigOperators",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {γ : Type w} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : Fintype ι] [inst_2 : (i : ι) → Zero (β i)]\n  [inst_3 : (i : ι) → (x : β i) → Decidable (x ≠ 0)] [inst_4 : CommMonoid γ] (v : Π₀ (i : ι), β i)\n  {f : (i : ι) → β i → γ}, (∀ (i : ι), f i 0 = 1) → v.prod f = ∏ i, f i (DFinsupp.equivFunOnFintype v i)"
    },
    {
      "name": "Finsupp.onFinset_prod",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : CommMonoid N] {s : Finset α} {f : α → M}\n  {g : α → M → N} (hf : ∀ (a : α), f a ≠ 0 → a ∈ s),\n  (∀ (a : α), g a 0 = 1) → (Finsupp.onFinset s f hf).prod g = ∏ a ∈ s, g a (f a)"
    },
    {
      "name": "Finsupp.prod_indicator_index",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : CommMonoid N] {s : Finset α} (f : α → M)\n  {h : α → M → N}, (∀ a ∈ s, h a 0 = 1) → (Finsupp.indicator s fun x x_1 => f x).prod h = ∏ x ∈ s, h x (f x)"
    },
    {
      "name": "Finsupp.prod_eq_single",
      "module_name": "Mathlib.Algebra.BigOperators.Finsupp.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_8} {N : Type u_10} [inst : Zero M] [inst_1 : CommMonoid N] {f : α →₀ M} (a : α)\n  {g : α → M → N}, (∀ (b : α), f b ≠ 0 → b ≠ a → g b (f b) = 1) → (f a = 0 → g a 0 = 1) → f.prod g = g a (f a)"
    }
  ]
}

